      "Epluchez les racines de wasabi et mettez-les au congélateur. Passez-les au robot-coupe afin de les réduire en purée fine. A l’aide d’une râpe Microplane, prélevez le zeste de pamplemousse et frottez-le avec 100 g de sucre semoule. Mélangez 165 g de sucre avec le stabilisateur et le glucose atomisé. Faites chauffer l’eau et le mélange sucre/zeste à 40°C et ajoutez le mélange précédent. Détendez le wasabi avec un peu de sirop et mélangez-le au restant du sirop. Mixez à l’aide d’un mixer plongeant. Filtrez-le et incorporez le jus de pamplemousse. Réservez une nuit au réfrigérateur. Le lendemain, mixez à nouveau et turbinez. Débarrassez en bac inox, en incorporant les cubes de pamplemousses confits petit à petit. Gardez au congélateur.",
