      "Remplissez des pots de 1 litre et de 140 millilitres. Fixez l’adhésif Sorbet Délicieux sur le couvercle. Sous le pot collez l’adhésif de la composition et de la DLC. Pour remplir les pots, utilisez une cuillère de glacier qui est bien appropriée à ce travail. Lissez les pots avec une palette inox et appliquez le couvercle. Stockez au congélateur.",
      "Conseil de consommation",
      "A garder au congélateur jusqu’à consommation.",
